CREATE TABLE IF NOT EXISTS rental_imports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, state_hash CHAR(64) UNIQUE NOT NULL, mapping_hash CHAR(64) NOT NULL, imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, counts_json JSON NOT NULL);
CREATE TABLE IF NOT EXISTS parties (id BIGINT PRIMARY KEY, name VARCHAR(255) NOT NULL, inn VARCHAR(20), address TEXT, contact VARCHAR(255), email VARCHAR(255), account_email VARCHAR(255), phone VARCHAR(100), blocked BOOLEAN NOT NULL DEFAULT FALSE, block_reason TEXT, version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL);
CREATE TABLE IF NOT EXISTS party_bank_accounts (id BIGINT AUTO_INCREMENT PRIMARY KEY, party_id BIGINT NOT NULL, bank VARCHAR(255), account VARCHAR(100), bik VARCHAR(20), correspondent_account VARCHAR(100), operational BOOLEAN NOT NULL DEFAULT FALSE, source_json JSON NOT NULL, FOREIGN KEY(party_id) REFERENCES parties(id));
CREATE TABLE IF NOT EXISTS cadastre (id BIGINT PRIMARY KEY, number VARCHAR(100) NOT NULL, area DECIMAL(18,4), floor VARCHAR(100), type VARCHAR(100), rentable BOOLEAN NOT NULL DEFAULT TRUE, version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL);
CREATE TABLE IF NOT EXISTS rental_objects (id BIGINT PRIMARY KEY, name VARCHAR(255) NOT NULL, type VARCHAR(100), area DECIMAL(18,4), floor VARCHAR(100), cadastre_id BIGINT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, free_since DATE NULL, version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL, FOREIGN KEY(cadastre_id) REFERENCES cadastre(id));
CREATE TABLE IF NOT EXISTS contracts (id BIGINT PRIMARY KEY, number VARCHAR(100) NOT NULL UNIQUE, party_id BIGINT NOT NULL, document_date DATE NULL, start_date DATE NULL, end_date DATE NULL, amount DECIMAL(20,2) NULL, status VARCHAR(40) NOT NULL, signed BOOLEAN NOT NULL DEFAULT FALSE, return_to VARCHAR(40), reason TEXT, template_type VARCHAR(60), version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL, FOREIGN KEY(party_id) REFERENCES parties(id));
CREATE TABLE IF NOT EXISTS contract_objects (contract_id BIGINT NOT NULL, object_id BIGINT NOT NULL, PRIMARY KEY(contract_id,object_id), FOREIGN KEY(contract_id) REFERENCES contracts(id), FOREIGN KEY(object_id) REFERENCES rental_objects(id));
CREATE TABLE IF NOT EXISTS contract_terms (id BIGINT AUTO_INCREMENT PRIMARY KEY, contract_id BIGINT NOT NULL, object_id BIGINT NOT NULL, start_date DATE NULL, end_date DATE NULL, amount DECIMAL(20,2) NULL, effective_date DATE NULL, source_json JSON NOT NULL, FOREIGN KEY(contract_id) REFERENCES contracts(id), FOREIGN KEY(object_id) REFERENCES rental_objects(id));
CREATE TABLE IF NOT EXISTS invoices (id BIGINT PRIMARY KEY, number VARCHAR(100) NOT NULL, contract_id BIGINT NOT NULL, kind VARCHAR(120), period VARCHAR(100), amount DECIMAL(20,2) NULL, paid DECIMAL(20,2) NULL, issued DATE NULL, due DATE NULL, status VARCHAR(40) NOT NULL, initial_invoice BOOLEAN NOT NULL DEFAULT FALSE, sent BOOLEAN NOT NULL DEFAULT FALSE, manual_review BOOLEAN NOT NULL DEFAULT FALSE, coverage_key VARCHAR(255) NULL UNIQUE, version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL, FOREIGN KEY(contract_id) REFERENCES contracts(id));
CREATE TABLE IF NOT EXISTS payments (id BIGINT PRIMARY KEY, party_id BIGINT NULL, amount DECIMAL(20,2) NOT NULL, payment_date DATE NULL, source VARCHAR(255), version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL, FOREIGN KEY(party_id) REFERENCES parties(id));
CREATE TABLE IF NOT EXISTS payment_allocations (payment_id BIGINT NOT NULL, invoice_id BIGINT NOT NULL, amount DECIMAL(20,2) NOT NULL, PRIMARY KEY(payment_id,invoice_id), FOREIGN KEY(payment_id) REFERENCES payments(id), FOREIGN KEY(invoice_id) REFERENCES invoices(id));
CREATE TABLE IF NOT EXISTS reservations (id BIGINT PRIMARY KEY, object_id BIGINT NOT NULL, party_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, until_date DATE NOT NULL, status VARCHAR(30) NOT NULL, comment TEXT, version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL, FOREIGN KEY(object_id) REFERENCES rental_objects(id), FOREIGN KEY(party_id) REFERENCES parties(id));
CREATE TABLE IF NOT EXISTS rental_documents (id BIGINT PRIMARY KEY, contract_id BIGINT NULL, number VARCHAR(100), kind VARCHAR(100), status VARCHAR(40), effective_date DATE NULL, version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL, FOREIGN KEY(contract_id) REFERENCES contracts(id));
CREATE TABLE IF NOT EXISTS rental_templates (id BIGINT PRIMARY KEY, name VARCHAR(255) NOT NULL, version INT NOT NULL, status VARCHAR(40) NOT NULL, body LONGTEXT, approved_by VARCHAR(255), approved_at DATE NULL, source_json JSON NOT NULL);
CREATE TABLE IF NOT EXISTS organization (id INT PRIMARY KEY, name VARCHAR(255), inn VARCHAR(20), address TEXT, email VARCHAR(255), vat DECIMAL(8,4) NULL, vat_from DATE NULL, version INT NOT NULL DEFAULT 1, source_json JSON NOT NULL);
CREATE TABLE IF NOT EXISTS organization_bank_accounts (id VARCHAR(100) PRIMARY KEY, organization_id INT NOT NULL, bank VARCHAR(255), account VARCHAR(100), bik VARCHAR(20), correspondent_account VARCHAR(100), is_primary BOOLEAN NOT NULL DEFAULT FALSE, source_json JSON NOT NULL, FOREIGN KEY(organization_id) REFERENCES organization(id));
CREATE TABLE IF NOT EXISTS rental_facts (id BIGINT AUTO_INCREMENT PRIMARY KEY, namespace VARCHAR(80) NOT NULL, source_key VARCHAR(180) NOT NULL, fact_json JSON NOT NULL, operative BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(namespace,source_key));
CREATE TABLE IF NOT EXISTS rental_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, contract_id BIGINT NULL, actor_id BIGINT UNSIGNED NULL, actor_role VARCHAR(40), action VARCHAR(100), description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, source_json JSON NULL);
CREATE TABLE IF NOT EXISTS rental_commands (command_key VARCHAR(100) PRIMARY KEY, action VARCHAR(100) NOT NULL, fingerprint CHAR(64) NOT NULL, result_json JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rental_files (id CHAR(32) PRIMARY KEY, entity_type VARCHAR(30) NOT NULL, entity_id BIGINT NOT NULL, version INT NOT NULL, kind VARCHAR(30), filename VARCHAR(255), path VARCHAR(255) NOT NULL, sha256 CHAR(64) NOT NULL, mime VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
